import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import bcrypt from "bcryptjs";
import { z } from "zod";
import { db } from "@/lib/db/prisma";

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

export const { handlers, auth, signIn, signOut } = NextAuth({
  session: { strategy: "jwt" },
  trustHost: true,
  providers: [
    Credentials({
      name: "Credentials",
      credentials: { email: { label: "Email" }, password: { label: "Password", type: "password" } },
      async authorize(credentials) {
        const parsed = loginSchema.safeParse(credentials);
        if (!parsed.success) return null;
        const user = await db.user.findUnique({ where: { email: parsed.data.email.toLowerCase() } });
        if (!user || !user.isActive) return null;
        const ok = await bcrypt.compare(parsed.data.password, user.passwordHash);
        if (!ok) return null;
        return {
          id: user.id,
          name: user.name,
          email: user.email,
          role: user.role,
          teamId: user.teamId,
          departmentId: user.departmentId,
        } as unknown as { id: string; name: string; email: string };
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        const u = user as unknown as { role?: string; teamId?: string | null; departmentId?: string | null };
        token.role = u.role;
        token.teamId = u.teamId;
        token.departmentId = u.departmentId;
      } else if (token.sub) {
        // refresh role/team on each request (cheap, keeps RBAC fresh)
        const dbUser = await db.user.findUnique({ where: { id: token.sub }, select: { role: true, teamId: true, departmentId: true, isActive: true } });
        if (!dbUser || !dbUser.isActive) return { ...token, role: undefined };
        token.role = dbUser.role;
        token.teamId = dbUser.teamId;
        token.departmentId = dbUser.departmentId;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        (session.user as unknown as Record<string, unknown>).id = token.sub;
        (session.user as unknown as Record<string, unknown>).role = token.role;
        (session.user as unknown as Record<string, unknown>).teamId = token.teamId;
        (session.user as unknown as Record<string, unknown>).departmentId = token.departmentId;
      }
      return session;
    },
  },
  pages: { signIn: "/login", error: "/login" },
});
